clearvars; close all; clc;
set(0,"DefaultAxesFontSize",8)
%[text] # Class: lspsys
%[text] JVsound, J.G. Vermond
disp(datetime("today")) %[output:3badfa7d]
%[text] ## Description
%[text] lspsys represents a loudspeaker system, including its environment.
%[text] ## Examples
% Initiation of an object:
lspsys1		= lspsys;

% Enclosure:
e			= comp.ClosedBox;
e.RearVolume	= 200e-3;

% Driver:
d			= comp.Driver;
d.Re		= 5.3;
d.Le		= 1.9e-3;
d.Qes		= 0.32;
d.Qms		= 5.6;
d.Fs		= 32;
d.Sd		= 1210e-4;
d.Vas		= 187e-3;

% Assign the enclosure to the loudspeaker system and the driver to the
% enclosure:
lspsys1.Enclosure			= e;
lspsys1.Enclosure.Driver	= d;

% We request the result object:
res							= lspsys1.createResult;
%[text] We plot the electric impedance of system
fig1				= figure; %[output:7de6a5fc]
ax1					= axes; hold on; grid on; %[output:7de6a5fc]
ax1.XScale			= "log"; %[output:7de6a5fc]
ax1.Title.String	= "Electric impedance of loudspeaker system"; %[output:7de6a5fc]
ax1.XLabel.String	= "[Hz]"; %[output:7de6a5fc]
ax1.YLabel.String	= "[\Omega]"; %[output:7de6a5fc]

plot(ax1,res.Frequency,abs(res.ElectricalImpedance),LineWidth=1.5) %[output:7de6a5fc]
%[text] ## Methods
%[text] ### Instance methods
%[text] - [`solve2PortNetwork`](matlab:open(fullfile(fileparts(fileparts(which('lspsys'))),'doc','lspsys','methods','solve2portnetworkdoc','solve2portnetworkdoc.m'))) — Combines all transmission matrices for the system and solves for diaphragm volume velocity and electric current.
%[text] - [`createResult`](matlab:open(fullfile(fileparts(fileparts(which('lspsys'))),'doc','lspsys','methods','createresultdoc','createresultdoc.m'))) — Solves the system and returns a populated `result` object with the loudspeaker's frequency-domain response. \


